package com.ethk3.novaonepro.strategyv2;
import java.io.*;
/** Bounded sparse cross-position lag groups with proximal L2 group shrinkage and exact joint head. */
public final class FamilyF01KernelR26 implements TemporalModelR26,TrainingDiagnosticsR26 {
    private final int L;private final boolean cross;private final double[][] w,bias=new double[10][10];private final int[][] ring;private long t,lifetimeUpdates;private boolean completeUpdateHistory=true;private TrainingDiagnosticsR26.Step last;
    public FamilyF01KernelR26(){this(3,true);}
    public FamilyF01KernelR26(int lags,boolean cross){if(lags<1||lags>8)throw new IllegalArgumentException("F01_LAGS");L=lags;this.cross=cross;w=new double[L*10][1000];ring=new int[L][10];}
    public void resetTemporalContext(){t=0;last=null;for(int[] row:ring)java.util.Arrays.fill(row,0);}
    public TrainingDiagnosticsR26.Step lastTrainingStep(){return last;}
    public long completedTrainingUpdates(){return lifetimeUpdates;}
    public String optimizerProtocol(){return "PROXIMAL_GROUP_L2_STEP002_LAMBDA00005_V3_"+(completeUpdateHistory?"KNOWN_LIFETIME":"UNKNOWN_PRIOR_UPDATES_COUNTED_SINCE_IMPORT");}
    public int stateWidth(){return 2;}
    double[][] scores(){return scores(bias,w);}
    private double[][] scores(double[][] biases,double[][] weights){double[][] s=new double[10][10];for(int p=0;p<10;p++)for(int n=0;n<10;n++){s[p][n]=biases[p][n];for(int l=0;l<Math.min(t,L);l++)for(int q=0;q<10;q++)if(cross||q==p)s[p][n]+=weights[l*10+q][(p*10+n)*10+ring[(int)((t-1-l)%L)][q]-1]/10;}return s;}
    public void predict(float[][] p,float[] st){ExactPermutationR26.Result r=ExactPermutationR26.infer(scores(),null);int groups=0;for(double[] row:w){double z=0;for(double x:row)z+=x*x;if(z>1e-20)groups++;}for(int i=0;i<10;i++)for(int j=0;j<10;j++)p[i][j]=(float)r.marginal[i][j];st[0]=groups;st[1]=(float)Math.log1p(t);}
    private String inputHash(){StringBuilder b=new StringBuilder("F01_FIXED_CAUSAL_LAGS_V3|").append(L).append('|').append(cross).append('|').append(t).append('|').append(lifetimeUpdates).append('|').append(completeUpdateHistory);for(int[] row:ring)for(int value:row)b.append('|').append(value);return PolicyIdentityR26.sha256(b.toString());}
    public void update(int[] draw){OnlineModelsSU2.requireDraw(draw);ExecutionBudgetR26.poll();if(t==Long.MAX_VALUE||lifetimeUpdates==Long.MAX_VALUE)throw new IllegalStateException("F01_UPDATE_CLOCK_CAPACITY");double[][] originalScores=scores();ExactPermutationR26.Result r=ExactPermutationR26.infer(originalScores,null);int[] target=new int[10];for(int p=0;p<10;p++)target[p]=draw[p]-1;double before=ExactPermutationR26.nll(originalScores,target,r),normSquared=0,deltaSquared=0;double[][] nextBias=new double[10][],nextWeights=new double[w.length][];for(int p=0;p<10;p++)nextBias[p]=bias[p].clone();for(int i=0;i<w.length;i++)nextWeights[i]=w[i].clone();
        for(int p=0;p<10;p++)for(int n=0;n<10;n++){double g=r.marginal[p][n]-(draw[p]==n+1?1:0);normSquared+=g*g;nextBias[p][n]-=.02*g;for(int l=0;l<Math.min(t,L);l++)for(int q=0;q<10;q++)if(cross||q==p)nextWeights[l*10+q][(p*10+n)*10+ring[(int)((t-1-l)%L)][q]-1]-=.02*g/10;}
        // Composite objective: exact joint NLL + lambda * sum of group L2 norms.
        // At an all-zero group choose the valid zero regularizer subgradient.
        for(int group=0;group<w.length;group++){ExecutionBudgetR26.poll();double oldSquared=0;for(double x:w[group])oldSquared+=x*x;double oldNorm=Math.sqrt(oldSquared);before+=.0005*oldNorm;int lag=group/10,q=group%10,digit=lag<Math.min(t,L)?ring[(int)((t-1-lag)%L)][q]-1:-1;
            for(int i=0;i<w[group].length;i++){int p=i/100,n=i/10%10;double smooth=digit>=0&&i%10==digit&&(cross||q==p)?(r.marginal[p][n]-(draw[p]==n+1?1:0))/10:0,gradient=smooth+(oldNorm==0?0:.0005*w[group][i]/oldNorm);normSquared+=gradient*gradient;}
            double norm=0;for(double x:nextWeights[group])norm+=x*x;double factor=norm==0?0:Math.max(0,1-.02*.0005/Math.sqrt(norm));for(int i=0;i<nextWeights[group].length;i++)nextWeights[group][i]*=factor;
        }
        double[][] afterScores=scores(nextBias,nextWeights);double after=ExactPermutationR26.nll(afterScores,target,ExactPermutationR26.infer(afterScores,null));for(int p=0;p<10;p++)for(int n=0;n<10;n++){double d=nextBias[p][n]-bias[p][n];deltaSquared+=d*d;}for(int group=0;group<w.length;group++){double norm=0;for(int i=0;i<w[group].length;i++){double x=nextWeights[group][i],d=x-w[group][i];norm+=x*x;deltaSquared+=d*d;}after+=.0005*Math.sqrt(norm);}
        TrainingDiagnosticsR26.Step step=new TrainingDiagnosticsR26.Step(lifetimeUpdates+1,before,after,Math.sqrt(normSquared),Math.sqrt(deltaSquared),inputHash(),"EXACT_PERMUTATION_JOINT_NLL_PLUS_00005_SUM_GROUP_L2;FIXED_PRE_LABEL_LAGS;GRADIENT=COMPOSITE_SUBGRADIENT_WITH_ZERO_REGULARIZER_SUBGRADIENT_AT_ZERO_GROUP;DELTA=ALL_BIASES_AND_GROUP_WEIGHTS");ExecutionBudgetR26.poll();
        for(int p=0;p<10;p++)System.arraycopy(nextBias[p],0,bias[p],0,10);for(int i=0;i<w.length;i++)System.arraycopy(nextWeights[i],0,w[i],0,w[i].length);ring[(int)(t%L)]=draw.clone();t++;lifetimeUpdates++;last=step;
    }
    void observeOnly(int[] draw){OnlineModelsSU2.requireDraw(draw);if(t==Long.MAX_VALUE)throw new IllegalStateException("F01_CONTEXT_CLOCK_CAPACITY");ring[(int)(t%L)]=draw.clone();t++;last=null;}
    String parameterHash(){StringBuilder b=new StringBuilder("F01_FROZEN_PARAMETERS_V1");for(double[][] m:new double[][][]{bias,w})for(double[] row:m)for(double x:row)b.append('|').append(Double.toHexString(x));return PolicyIdentityR26.sha256(b.toString());}
    public void write(DataOutput o)throws IOException{o.writeInt(0x26010003);o.writeInt(L);o.writeBoolean(cross);o.writeLong(t);for(int[] row:ring)for(int x:row)o.writeInt(x);for(double[] row:bias)for(double x:row)o.writeDouble(x);for(double[] row:w)for(double x:row)o.writeDouble(x);o.writeLong(lifetimeUpdates);o.writeBoolean(completeUpdateHistory);}
    public void read(DataInput in)throws IOException{int header=in.readInt();if(header==0x26010002||header==0x26010003){if(in.readInt()!=L||in.readBoolean()!=cross)throw new IOException("F01_GRAPH_BINDING");}else if(header!=0x26010001||L!=3||!cross)throw new IOException("F01_ABI");long clock=in.readLong();if(clock<0)throw new IOException("F01_CURSOR");int[][] history=new int[L][10];for(int[] row:history)for(int i=0;i<10;i++){row[i]=in.readInt();if(row[i]<0||row[i]>10)throw new IOException("F01_DRAW");}for(int lag=0;lag<Math.min(clock,L);lag++)try{OnlineModelsSU2.requireDraw(history[(int)((clock-1-lag)%L)]);}catch(IllegalArgumentException bad){throw new IOException("F01_HISTORY_DRAW",bad);}double[][] restoredBias=new double[10][10],restoredWeights=new double[w.length][1000];for(double[][] m:new double[][][]{restoredBias,restoredWeights})for(double[] row:m)for(int i=0;i<row.length;i++){row[i]=in.readDouble();if(!Double.isFinite(row[i])||Math.abs(row[i])>1e6)throw new IOException("F01_STATE");}long updates=0;boolean known=false;if(header==0x26010003){updates=in.readLong();int flag=in.readUnsignedByte();if(updates<0||flag>1)throw new IOException("F01_UPDATE_HISTORY");known=flag==1;}
        for(int i=0;i<L;i++)System.arraycopy(history[i],0,ring[i],0,10);for(int p=0;p<10;p++)System.arraycopy(restoredBias[p],0,bias[p],0,10);for(int i=0;i<w.length;i++)System.arraycopy(restoredWeights[i],0,w[i],0,1000);t=clock;lifetimeUpdates=updates;completeUpdateHistory=known;last=null;
    }
}
